(function(){
var CSS_B64="";
var HTML_B64="";
function d(b){return decodeURIComponent(escape(window.atob(b)));}
function inject(){
 if(document.getElementById('aocp-header-host'))return;
 var host=document.createElement('div');
 host.id='aocp-header-host';
 host.style.cssText='display:block;width:100%;position:relative;z-index:50;';
 document.body.insertBefore(host,document.body.firstChild);
 var r=host.attachShadow({mode:'open'});
 r.innerHTML='<style>'+d(CSS_B64)+'</style>'+d(HTML_B64);
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',inject);else inject();
})();